protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 changed the default discriminator from "Discriminator" to "$type".
        // Preserve the old name so existing 500K documents and direct SQL queries
        // that reference c.Discriminator continue to work.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed the id format from "Product|123" to just "123".
        // Preserve the old compound format so existing documents remain accessible.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // Removed HasIndex — EF Core 9 Cosmos provider now throws on HasIndex.
    // Cosmos DB indexing is managed via the container's indexing policy, not EF Core.
}

